25	    if (this.cursors.left.isDown) body.setVelocityX(-speed);
26	    if (this.cursors.right.isDown) body.setVelocityX(speed);
27	    if (this.cursors.up.isDown) body.setVelocityY(-speed);
28	    if (this.cursors.down.isDown) body.setVelocityY(speed);
